<?php
session_start(); include('dbstring.php'); include('check-login.php'); include_once('administration-ops-utils.php'); administration_ops_ensure_tables($con);
if(!administration_ops_is_lead()){ header('location:index.php'); exit(); }
$message='';
if(isset($_POST['save_case'])){
    $student=trim((string)($_POST['studentid']??'')); $category=trim((string)($_POST['category']??'')); $date=trim((string)($_POST['incidentdate']??'')); $summary=trim((string)($_POST['summary']??'')); $action=trim((string)($_POST['actiontaken']??'')); $follow=trim((string)($_POST['followupdate']??''));
    if($student!=='' && $category!=='' && $date!=='' && $summary!==''){
        $id=administration_ops_id('WEL'); $parent=isset($_POST['parentcontacted'])?1:0; $status='open'; $by=$_SESSION['USERID'];
        $stmt=mysqli_prepare($con,'INSERT INTO tblstudentwelfarecase(caseid,studentid,category,incidentdate,summary,actiontaken,parentcontacted,followupdate,status,recordedby) VALUES(?,?,?,?,?,?,?,?,?,?)');
        mysqli_stmt_bind_param($stmt,'ssssssisss',$id,$student,$category,$date,$summary,$action,$parent,$follow,$status,$by); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); $message='Welfare case recorded.';
    }else{$message='Complete the student, category, date, and summary.';}
}
if(isset($_POST['update_case'])){ $id=trim((string)$_POST['caseid']); $status=in_array($_POST['status']??'',array('open','monitoring','closed'),true)?$_POST['status']:'open'; $action=trim((string)$_POST['actiontaken']); $follow=trim((string)$_POST['followupdate']); $parent=isset($_POST['parentcontacted'])?1:0; $stmt=mysqli_prepare($con,'UPDATE tblstudentwelfarecase SET status=?,actiontaken=?,followupdate=?,parentcontacted=?,updatedat=NOW() WHERE caseid=?'); mysqli_stmt_bind_param($stmt,'sssis',$status,$action,$follow,$parent,$id); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); $message='Welfare case updated.'; }
$students=[]; $res=mysqli_query($con,"SELECT userid,CONCAT_WS(' ',firstname,othernames,surname) name FROM tblsystemuser WHERE systemtype='Student' AND status='active' ORDER BY firstname,surname"); if($res)while($row=mysqli_fetch_assoc($res))$students[]=$row;
$filter=in_array($_GET['status']??'',array('open','monitoring','closed'),true)?$_GET['status']:'open'; $filterEsc=mysqli_real_escape_string($con,$filter); $cases=mysqli_query($con,"SELECT wc.*,CONCAT_WS(' ',su.firstname,su.othernames,su.surname) student_name FROM tblstudentwelfarecase wc LEFT JOIN tblsystemuser su ON su.userid=wc.studentid WHERE wc.status='$filterEsc' ORDER BY COALESCE(wc.followupdate,'9999-12-31') ASC,wc.incidentdate DESC LIMIT 100");
$counts=['open'=>0,'monitoring'=>0,'closed'=>0]; $countRes=mysqli_query($con,"SELECT status,COUNT(*) total FROM tblstudentwelfarecase GROUP BY status"); if($countRes)while($row=mysqli_fetch_assoc($countRes))$counts[$row['status']]=(int)$row['total'];
?>
<!doctype html><html><head><?php include('title.php');include('links.php');?><link rel="stylesheet" href="css/headmaster-dashboard.css"><link rel="stylesheet" href="css/assistant-admin-ops.css"></head><body class="hm-page aops-page"><div class="header"><?php include('menu.php');?></div><main class="hm-shell"><aside class="hm-sidebar"><div class="hm-sidebar__inner"><?php include('welcome.php');include('menuboard.php');?></div></aside><section class="hm-main"><section class="hm-hero hm-hero--single aops-hero"><div><span class="hm-kicker">Student welfare & discipline</span><h1>Welfare case register</h1><p>Record concerns, support actions, parent contact, and follow-up dates in one protected operational register.</p><div class="hm-hero__footer"><div class="hm-context"><span><i class="fa fa-heart"></i> Welfare follow-up</span><span><i class="fa fa-shield"></i> Administration oversight</span></div><a class="aops-back" href="assistant-head-administration-page.php"><i class="fa fa-arrow-left"></i> Dashboard</a></div></div></section><?php if($message!==''){?><div class="aops-flash"><?php echo administration_ops_escape($message);?></div><?php }?><section class="aops-stats"><div class="aops-stat"><i class="fa fa-folder-open"></i><span>Open cases<strong><?php echo number_format($counts['open']);?></strong></span></div><div class="aops-stat"><i class="fa fa-eye"></i><span>Monitoring<strong><?php echo number_format($counts['monitoring']);?></strong></span></div><div class="aops-stat"><i class="fa fa-check-circle"></i><span>Closed<strong><?php echo number_format($counts['closed']);?></strong></span></div></section><section class="aops-grid"><section class="aops-panel"><div class="hm-panel__head"><div><span class="hm-section__eyebrow">New case</span><h2>Record a welfare concern</h2></div></div><form method="post" class="aops-form"><label>Student<select name="studentid" required><option value="">Select student</option><?php foreach($students as $student){?><option value="<?php echo administration_ops_escape($student['userid']);?>"<?php echo (($_GET['studentid']??'')===$student['userid'])?' selected':'';?>><?php echo administration_ops_escape($student['name']);?></option><?php }?></select></label><div class="aops-inline"><label>Category<select name="category" required><option value="">Select</option><option>Discipline</option><option>Health</option><option>Attendance</option><option>Counselling</option><option>Bullying / Safety</option><option>Family / Welfare</option></select></label><label>Date<input type="date" name="incidentdate" value="<?php echo date('Y-m-d');?>" required></label></div><label>Summary<textarea name="summary" required placeholder="Describe the concern factually and respectfully"></textarea></label><label>Initial action<textarea name="actiontaken" placeholder="Support, meeting, referral, or action taken"></textarea></label><div class="aops-inline"><label>Follow-up date<input type="date" name="followupdate"></label><label><input type="checkbox" name="parentcontacted" value="1"> Parent / guardian contacted</label></div><button class="aops-button" name="save_case"><i class="fa fa-save"></i> Save welfare case</button></form></section><section class="aops-panel"><div class="hm-panel__head"><div><span class="hm-section__eyebrow">Case follow-up</span><h2>Welfare cases</h2></div><div class="aops-filter"><a class="<?php echo $filter==='open'?'is-active':'';?>" href="?status=open">Open</a><a class="<?php echo $filter==='monitoring'?'is-active':'';?>" href="?status=monitoring">Monitoring</a><a class="<?php echo $filter==='closed'?'is-active':'';?>" href="?status=closed">Closed</a></div></div><div class="aops-table-wrap"><table class="aops-table"><thead><tr><th>Student / concern</th><th>Follow-up</th><th>Update</th></tr></thead><tbody><?php if($cases&&mysqli_num_rows($cases)>0){while($case=mysqli_fetch_assoc($cases)){?><tr><td><strong><?php echo administration_ops_escape($case['student_name']?:$case['studentid']);?></strong><small><?php echo administration_ops_escape($case['category']);?> · <?php echo administration_ops_escape($case['summary']);?></small></td><td><?php echo $case['followupdate']?date('d M Y',strtotime($case['followupdate'])):'Not set';?><small><?php echo $case['parentcontacted']?'Parent contacted':'Parent not yet recorded';?></small></td><td><form method="post" class="aops-form"><input type="hidden" name="caseid" value="<?php echo administration_ops_escape($case['caseid']);?>"><select name="status"><option<?php echo $case['status']==='open'?' selected':'';?>>open</option><option<?php echo $case['status']==='monitoring'?' selected':'';?>>monitoring</option><option<?php echo $case['status']==='closed'?' selected':'';?>>closed</option></select><input name="followupdate" type="date" value="<?php echo administration_ops_escape($case['followupdate']);?>"><textarea name="actiontaken" placeholder="Update action"><?php echo administration_ops_escape($case['actiontaken']);?></textarea><label><input type="checkbox" name="parentcontacted" value="1"<?php echo $case['parentcontacted']?' checked':'';?>> Parent contacted</label><button class="aops-button" name="update_case">Update</button></form></td></tr><?php }}else{?><tr><td colspan="3" class="aops-empty">No cases in this view.</td></tr><?php }?></tbody></table></div></section></section></section></main></body></html>